import{z as r,x as B,o as E,c as A,q as o,j as s,D as e,d as t,s as l,S as d,b as n}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"注意力掩码与填充","description":"","frontmatter":{"title":"注意力掩码与填充","date":"2026-09-27T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/attention-mask-padding.md","filePath":"llm/attention-mask-padding.md","lastUpdated":1791413859000}'),p={name:"llm/attention-mask-padding.md"};function g(D,a,m,c,h,k){const i=B("Mermaid");return E(),A("div",null,[a[2]||(a[2]=o('<h1 id="注意力掩码与填充" tabindex="-1">注意力掩码与填充 <a class="header-anchor" href="#注意力掩码与填充" aria-label="Permalink to &quot;注意力掩码与填充&quot;">​</a></h1><div class="epigraph"><p>batch 里 8 个序列 7 个是占位符：掩码没做对，占位符就在注意力里说话——一句 padding 的坑，从训练贯到推理。</p><footer>—— 据 HuggingFace Transformers 掩码文档；FlashAttention 变长 varlen 接口设计</footer></div><p><a href="/llm/unicode-tokenization">Unicode 分词</a>把字节变 token，本课把 token 变 batch：长短不一的序列要拼进同一个矩形张量，缺口是<strong>padding 与注意力掩码</strong>——占位 token 凭什么不许被注意、又凭什么不算损失。这一课的坑贯穿预训、SFT、推理三段。本课不做 FlashAttention 的内核实现。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>矩形张量的代价：batch 内最长序列 4096、其余 200，padding 占 95% 计算量。三个必须答对的问题：注意力要不要看见 padding（不要）；loss 要不要算 padding 位置（不要）；位置编码要不要给 padding 编号（争议点）。答错任何一条，模型学到「句尾越多 padding 越自信」之类的鬼东西。</p><p><span class="marginnote">术语翻译：padding token = 占位符（ID 常为 0）；attention mask = 加性掩码（allowed 处加 0，禁处加 \\(-\\infty\\) 再 softmax）；padding side = 左补还是右补——decoder-only 推理必须左补，否则生成位置被占位符顶乱。</span></p><p><span class="marginnote">数字实例：batch=8、最长 4096、平均 300。右补 naive 方案算力 ∝ 8×4096²，有效算力仅 8×300²/8×4096² ≈ 0.5%——99.5% 的 FLOPs 花在占位符上。varlen 打包后 ∝ Σ300²，利用率回到 90%+。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>正确姿势三层。<strong>算对</strong>：attention mask 做成加性偏置进 softmax 前，padding 位 \\(-\\infty\\)；loss 乘 mask（或标签位填 -100 由交叉熵忽略）；<strong>算快</strong>：packing（把多个短序列拼进一个 4096 窗、配 block-diagonal 掩码互不见）或 FlashAttention varlen（内核按真实长度调度，不 materialize 掩码）；<strong>摆对</strong>：训练右补（位置编号连续），推理左补（新 token 永远在末位）——两者混用是「怎么突然变傻」的经典悬案。</p>',9)),(E(),s(d,null,{default:e(()=>[l(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22batch%3A%20%E9%95%BF%E7%9F%AD%E4%B8%8D%E4%B8%80%22%5D%20--%3E%20B%7B%22%E6%8E%A9%E7%A0%81%E5%A7%BF%E5%8A%BF%22%7D%0A%20%20B%20--%3E%7C%22%E5%8A%A0%E6%80%A7%20%E2%88%92%E2%88%9E%22%7C%20C%5B%22padding%20%E4%B8%8D%E8%A2%AB%E6%B3%A8%E6%84%8F%22%5D%0A%20%20B%20--%3E%7C%22loss%20%C3%97%20mask%22%7C%20D%5B%22padding%20%E4%B8%8D%E8%BF%9B%E6%A2%AF%E5%BA%A6%22%5D%0A%20%20E%7B%22%E4%BD%8D%E7%BD%AE%E6%80%8E%E4%B9%88%E6%91%86%3F%22%7D%20--%3E%7C%22%E8%AE%AD%E7%BB%83%E5%8F%B3%E8%A1%A5%22%7C%20F%5B%22%E4%BD%8D%E7%BD%AE%E7%BC%96%E5%8F%B7%E8%BF%9E%E7%BB%AD%22%5D%0A%20%20E%20--%3E%7C%22%E6%8E%A8%E7%90%86%E5%B7%A6%E8%A1%A5%22%7C%20G%5B%22%E7%94%9F%E6%88%90%E4%BD%8D%E6%B0%B8%E8%BF%9C%E6%9C%AB%E5%B0%BE%22%5D%0A%20%20H%5B%22packing%2Fvarlen%22%5D%20--%3E%20I%5B%22%E7%AE%97%E5%8A%9B%E4%B8%8D%E8%8A%B1%E5%9C%A8%E5%8D%A0%E4%BD%8D%E7%AC%A6%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("p",null,[n("span",{class:"marginnote"},"直觉类比：矩形 batch 像一排不同身高的人合影，摄影师（张量）要求大家站一样高——矮的脚下垫箱子（padding）。掩码是「拍照时忽略垫箱」，packing 是「让矮的两人叠罗汉凑一个身高位」，varlen 是「换无级伸缩的照相馆，每人按真实身高占相纸」。")],-1)),a[4]||(a[4]=n("h2",{id:"机制",tabindex:"-1"},[t("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=n("p",null,[t("因果掩码 × padding 掩码的合取：每个位置 \\(j\\) 能被 \\(i\\) 看见当且仅当 \\(j\\le i\\)（因果）"),n("strong",null,"且"),t(" \\(j\\) 非 padding。实现上两个加性偏置相加进 logits——数学上等价于「可见集合取交」。位置编码的坑更深：右补时位置编号按物理索引走，padding 占了编号但被掩码屏蔽——无害；"),n("strong",null,"推理左补"),t("时若沿用「物理索引」给真实 token 编号，第一个真实 token 的 position id 会随 batch 内长度变化而漂移，RoPE 相位错乱——这是「同一个 prompt batch 内答案不同」的机制。训练时的第二个幽灵：packing 若不做注意力隔离，序列 A 的结尾会注意序列 B 的开头，模型学到「无关联文档的粘合」——预训污染源之一。")],-1)),(E(),s(d,null,{default:e(()=>[l(i,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22padding%20%E4%B8%BA%E4%BD%95%E5%BF%85%E9%A1%BB%E5%B1%8F%E8%94%BD%3F%22%7D%20--%3E%20R%5B%22%E5%8D%A0%E4%BD%8D%E7%AC%A6%E6%97%A0%E8%AF%AD%E4%B9%89%22%5D%0A%20%20R%20--%3E%20S%5B%22%E8%A2%AB%E6%B3%A8%E6%84%8F%20%E2%86%92%20%E5%AD%A6%E5%88%B0%E5%81%87%E7%9B%B8%E5%85%B3%22%5D%0A%20%20T%7B%22%E5%B7%A6%E8%A1%A5%E4%B8%BA%E4%BD%95%E6%94%B9%20position%3F%22%7D%20--%3E%20U%5B%22%E7%89%A9%E7%90%86%E7%B4%A2%E5%BC%95%20%3D%20%E7%9C%9F%E5%AE%9E%E9%95%BF%E5%BA%A6%E7%9B%B8%E5%85%B3%22%5D%0A%20%20U%20--%3E%20V%5B%22RoPE%20%E7%9B%B8%E4%BD%8D%E6%BC%82%E7%A7%BB%22%5D%0A%20%20V%20--%3E%20W%5B%22%E5%90%8C%20prompt%20batch%20%E5%86%85%E7%AD%94%E6%A1%88%E6%BC%82%E7%A7%BB%22%5D%0A%20%20X%7B%22packing%20%E7%9A%84%E5%9D%91%3F%22%7D%20--%3E%20Y%5B%22%E6%96%87%E6%A1%A3%E4%BA%92%E7%9B%B8%E5%8F%AF%E8%A7%81%22%5D%0A%20%20Y%20--%3E%20Z%5B%22%E9%9C%80%20block-diagonal%20%E9%9A%94%E7%A6%BB%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p><span class="marginnote">常见误区：以为「padding=0 token 无害」——零号 embedding 也是向量，注意它会歪掉整个分布；另一误区是 loss 不乘 mask 却发现「模型爱输出句号」——padding 位的目标标签也被算了损失，模型学会了「凑长度」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>工程真相：这三层坑的当代答案是<strong>不拼矩形</strong>——FlashAttention 的 varlen 接口按 cu_seqlens（累积长度）调度，掩码根本不落盘；训练侧 packing + 文档级掩码是预训标配。遗留风险集中在自研 trainer：自己的 attention 实现里 mask 加错维度（[B,1,1,S] vs [B,1,S,S] 是永恒考点）。生成式推理的左补陷阱在 kv-cache 复用（prefix caching）下更绕——缓存的前缀与左补位如何对齐，每个推理框架都有自己的约定。与<a href="/llm/attention-sink">注意力下沉</a>的呼应：流式推理里首批 token 被强制保留当「注意垃圾桶」，本质是掩码策略在长上下文下的延伸。</p><p><span class="marginnote">直觉类比：矩阵 batch 像拼车算法的固定四座——三个人时剩一个空座（padding），规矩是「空座不许说话（掩码）、不计车费（loss）、不占座位号（位置）」；packing 是把三家三口塞进一辆车但中间立隔音板（block-diagonal），varlen 干脆叫了三辆专车。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>掩码三问：注意不见、loss 不算、位置不编——答错一条就污染训练。</li><li>左补/右补之争只在推理生成侧致命，RoPE 相位是机制根源。</li><li>当代正解是 varlen/packing 不拼矩形；自研 attention 必查掩码维度。</li><li>出处：HuggingFace Transformers 文档；FlashAttention-2 varlen 接口；GPT 系训练实践。</li></ul>',6))])}const u=r(p,[["render",g]]);export{f as __pageData,u as default};
